    g_matrixStackTop--;
    g_eventQueueEnd = *(unsigned int *)(g_matrixStackTop * 4);
    g_matrixStackTop--;
    g_eventQueueIdx = *(unsigned int *)(g_matrixStackTop * 4);
    g_matrixStackTop--;
